"""Reproducible 0.2 curriculum: explicit beginner steps and executable checks."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CONTENT=ROOT/'content'
lessons=json.loads((CONTENT/'lessons.json').read_text(encoding='utf-8'))
solutions=json.loads((ROOT/'frontend/tests/solutions.json').read_text(encoding='utf-8'))
original={l['id']:l for l in lessons}

def add(lang,slug,title,tag,theory,example,task,starter,solution,tests,steps,hints=None,setup=''):
    lid=f'{lang}-{slug}'
    lesson=dict(id=lid,language=lang,title=title,topic=title,section='С самого начала',order=0,level='Beginner',minutes=8,theory=theory,syntax=example,examples=[example],task=task,starterCode=starter,setupSql=setup,concepts=[tag],walkthrough=steps,hints=hints or [steps[0],steps[min(1,len(steps)-1)],'Сравните свой код с небольшим примером выше. Подставьте значения из условия задания.'],commonMistakes='Проверьте написание имён, кавычки и ожидаемый результат. Сначала Run, затем Check.',solutionExplanation=steps[-1],xp=40,tests=[])
    for i,(label,expression,expected) in enumerate(tests):
        lesson['tests'].append(dict(id=f't{i+1}',label=label,expected=expected,**({'expression':expression} if lang=='python' else {'query':expression})))
    original[lid]=lesson;solutions[lid]=solution
    return lesson

def py(slug,title,tag,theory,example,task,starter,solution,tests,steps):
    return add('python',slug,title,tag,theory,example,task,starter,solution,tests,steps)

py('first-print','Первая программа: показать сообщение','start',
   'Программа — список точных команд для компьютера. Редактор справа хранит этот список, а кнопка Run выполняет его. Результат появляется в панели OUTPUT под редактором. Чтобы начать, не нужно ничего устанавливать.\n\nКоманда print() показывает значение. Круглые скобки означают вызов команды. Текст внутри кавычек называется строкой: Python выводит её содержимое, а сами кавычки не показывает. Можно использовать одинаковые одинарные или двойные кавычки.\n\nКод читается сверху вниз. Сначала попробуйте пример, затем измените сообщение. Check проверяет ваше решение, а не просто запускает его.',
   'print("Привет, мир!")','Выведите ровно одну строку: Привет, DevForge!','',
   'print("Привет, DevForge!")',[('Сообщение в консоли','_stdout','Привет, DevForge!\n')],
   ['Напишите print — имя команды вывода.','Внутри скобок поместите текст в кавычках.','Нажмите Run: строка появится в OUTPUT. Check сравнит текст с условием.'])
py('comments','Строки программы и комментарии','start',
   'Один файл может содержать несколько команд. Python выполняет их по очереди сверху вниз. Каждый print по умолчанию заканчивает вывод переходом на новую строку.\n\nТекст после # — комментарий для человека. Он не выполняется. Пустые строки тоже можно использовать для удобства чтения. Комментарий полезно писать о причине действия, а не повторять очевидное.\n\nПока пишите команды от самого левого края: лишний отступ в начале простой команды может вызвать IndentationError.',
   '# Два сообщения по очереди\nprint("Начало")\nprint("Конец")','Выведите сначала Старт, затем Готово на новой строке. Добавьте поясняющий комментарий для себя.','# Здесь можно написать комментарий\n',
   '# Проверяем порядок\nprint("Старт")\nprint("Готово")',[('Порядок вывода','_stdout','Старт\nГотово\n')],['Первая команда выводит Старт.','Следующая строка кода содержит второй print.','Комментарий не добавляет текст в OUTPUT; каждая команда print даёт свою строку.'])
py('numbers','Числа: компьютер как калькулятор','numbers',
   'Числа в коде можно писать без кавычек. Python вычисляет выражение, а print показывает ответ. Символ * означает умножение, / — деление. Для дробной части используется точка: 2.5, а не запятая.\n\nУмножение и деление выполняются раньше сложения. Скобки меняют порядок: (2 + 3) * 4 даст 20, а 2 + 3 * 4 даст 14. Сначала вычисляется содержимое скобок, затем остальное выражение.\n\nЧисло 12 и текст "12" — разные значения: текст нельзя использовать как число без преобразования.',
   'print(2 + 3 * 4)\nprint((2 + 3) * 4)','Выведите результат выражения (8 + 4) * 3.','print(0)',
   'print((8 + 4) * 3)',[('Результат арифметики','_stdout','36\n')],['Сложите 8 и 4 внутри скобок.','Умножьте результат на 3 через *.','Передайте всё выражение в print: ответ равен 36.'])
py('text-quotes','Текст, кавычки и соединение строк','strings',
   'Строка хранит текст: имя, сообщение или название. Открывающая и закрывающая кавычки должны совпадать. Если текст содержит апостроф, удобнее окружить его двойными кавычками.\n\nОператор + для строк соединяет их. Он не добавляет пробел автоматически. "Добрый" + "день" даст "Добрыйдень"; пробел нужно включить в одну строку.\n\nprint("2" + "3") выводит 23, а print(2 + 3) — 5. Кавычки меняют смысл значений.',
   'print("Добрый " + "день")','Соедините строки Привет,  и Ada и выведите Привет, Ada.','print("")',
   'print("Привет, " + "Ada")',[('Строка с пробелом','_stdout','Привет, Ada\n')],['Первая строка заканчивается запятой и пробелом.','Соедините её со второй строкой с помощью +.','Кавычки не входят в результат; пробел входит.'])
py('variable-step','Переменная — имя для значения','variables',
   'Представьте подписанную коробку: имя помогает найти значение позднее. В коде score = 10 связывает имя score с числом 10. Это присваивание, а не математическое равенство.\n\nСправа от = сначала вычисляется значение, затем оно сохраняется под именем слева. Команда score = score + 5 берёт прежнее число, прибавляет 5 и заменяет прежнее значение.\n\nКогда print получает имя без кавычек, он показывает содержимое переменной. print("score") показывает слово score. Имена учитывают регистр: Score и score различаются.',
   'score = 10\nscore = score + 5\nprint(score)','Создайте coins со значением 10, прибавьте к нему 3 и выведите итог.','coins = 10\n# Измените coins\nprint(coins)',
   'coins = 10\ncoins = coins + 3\nprint(coins)',[('Значение переменной','coins',13),('Вывод','_stdout','13\n')],['Сначала присвойте начальное значение.','Прочитайте прежнее coins справа от = и добавьте 3.','После присваивания coins содержит 13; print(coins) показывает это число.'])
py('conversion','Преобразование текста в число','types',
   'Данные часто приходят в виде текста. В строке "12" находятся два символа, а не готовое число для вычислений. int("12") превращает такую строку в целое число 12. float("2.5") создаёт дробное число.\n\nstr(12) выполняет обратное действие и создаёт строку "12". Преобразование возможно не всегда: int("кот") вызывает ValueError, потому что слово не описывает число.\n\nПрисваивайте преобразованный результат новой переменной: исходная строка сама по себе не меняется.',
   'text = "7"\nnumber = int(text)\nprint(number + 2)','В text хранится "12". Создайте number как число из text и result как number + 8.','text = "12"\n# Создайте number и result\n',
   'text="12"\nnumber=int(text)\nresult=number+8',[('Число и тип','[number,type(number).__name__]',[12,'int']),('Сумма','result',20)],['int(text) преобразует строку.','Сохраните число в number.','Сложите number и 8; result должен содержать число 20.'])
py('booleans','Да или нет: логические значения','logic',
   'Некоторые данные имеют только два состояния: включено или выключено, выполнено или нет. Python использует True и False. Это тип bool; первая буква обязательна заглавная.\n\nnot меняет значение на противоположное. and даёт True, если обе части истинны. or даёт True, если истинна хотя бы одна часть. Скобки помогают читать сложное выражение.\n\nСтрока "False" — непустой текст, а не логическое False. Не заключайте логические значения в кавычки.',
   'has_ticket = True\nis_closed = False\ncan_enter = has_ticket and not is_closed','Создайте has_key=True и locked=False. can_open должно означать: ключ есть И дверь не заблокирована.','has_key = True\nlocked = False\ncan_open = False',
   'has_key=True\nlocked=False\ncan_open=has_key and not locked',[('Входные значения','[has_key,locked]',[True,False]),('Решение','[can_open,type(can_open).__name__]',[True,'bool'])],['Выражение not locked проверяет отсутствие блокировки.','Объедините его с has_key через and.','Результат — True, потому что оба требования выполнены.'])
py('comparisons','Сравнения и границы','logic',
   'Сравнение возвращает True или False. == проверяет равенство, != — различие, > и < — строгие границы. >= и <= включают саму границу.\n\nОдин знак = сохраняет значение, два знака == сравнивают. Чтобы узнать, достаточно ли человеку 18 лет, нужно age >= 18: возраст ровно 18 тоже подходит.\n\nРезультат сравнения можно сохранить в переменной, чтобы затем использовать его в условии.',
   'temperature = 20\nis_warm = temperature >= 18\nprint(is_warm)','Для age=18 создайте is_adult, проверяющую age >= 18, и is_teen, проверяющую age < 18.','age = 18\n',
   'age=18\nis_adult=age>=18\nis_teen=age<18',[('Граница 18','is_adult',True),('Младше 18','is_teen',False)],['Проверьте, включается ли 18 в нужный диапазон.','Для совершеннолетия используйте >=, для младшего возраста <.','На границе первое выражение истинно, второе ложно.'])
py('if-first','Первое условие и отступы','conditions',
   'Иногда команда нужна только при выполнении условия. if означает «если». После условия ставится двоеточие, а команды выбранной ветки сдвигаются вправо на четыре пробела.\n\nelse означает «иначе» и стоит на одном уровне с if. В программе выполнится только одна из двух веток. Отступ — часть синтаксиса Python, поэтому редактор помогает ставить его автоматически.\n\nПроследите пример сначала с положительным balance, затем с нулём. Меняется только входное значение, но выбирается другая ветка.',
   'balance = 5\nif balance > 0:\n    message = "Есть средства"\nelse:\n    message = "Пусто"\nprint(message)','При temperature=5 сохраните message="Холодно", если температура ниже 10, иначе message="Тепло".','temperature = 5\n# Добавьте if / else\n',
   'temperature=5\nif temperature<10:\n    message="Холодно"\nelse:\n    message="Тепло"',[('Выбранная ветка','message','Холодно')],['Запишите if temperature < 10: без отступа.','Внутри ветки присвойте сообщение с отступом.','else покрывает оставшиеся температуры. При 5 выбирается Холодно.'])
py('range-first','Повторение без копирования: for','loops',
   'Цикл повторяет одно действие. for number in range(3) последовательно подставляет в number значения 0, 1 и 2. После каждого значения выполняется тело с отступом.\n\nrange(start, stop) начинает с start и останавливается перед stop. Поэтому для чисел 1, 2, 3 нужна правая граница 4. Это правило удобно запомнить: правая граница не включается.\n\nНе пишите три одинаковые команды вручную, когда данные можно перебрать циклом.',
   'for number in range(1, 4):\n    print(number)','Выведите числа 1, 2, 3, 4, 5, каждое с новой строки, с помощью for.','# Начните цикл\n',
   'for number in range(1,6):\n    print(number)',[('Последовательность','_stdout','1\n2\n3\n4\n5\n')],['Первое значение диапазона — 1.','Чтобы включить 5, используйте stop=6.','print внутри цикла получает очередное число.'])
py('while-counter','Цикл while: когда остановиться','loops',
   'while означает «пока». До каждой итерации Python проверяет условие. Если оно True, выполняется тело; если False — цикл заканчивается.\n\nСчётчик нужно изменять внутри цикла, иначе условие может остаться истинным навсегда. В примере count уменьшается после каждого вывода. Когда он становится нулём, count > 0 ложно.\n\nЕсли программа зависла, нажмите Stop. В DevForge есть также автоматический таймаут.',
   'count = 3\nwhile count > 0:\n    print(count)\n    count -= 1','Начните с count=3. Выведите 3, 2, 1 и завершите цикл; итоговый count должен быть 0.','count = 3\n# Добавьте while\n',
   'count=3\nwhile count>0:\n    print(count)\n    count-=1',[('Обратный отсчёт','_stdout','3\n2\n1\n'),('Состояние после цикла','count',0)],['Условие цикла: count > 0.','Уменьшайте count в теле, после print.','После последней итерации count равен нулю и цикл завершается.'])
py('list-index','Первый список и индексы','collections',
   'Список хранит несколько значений в заданном порядке. Значения перечисляются в квадратных скобках через запятую. Например, три имени удобно хранить в одной переменной, а не в трёх разных.\n\nИндекс — номер позиции. В Python первая позиция имеет индекс 0, вторая — 1. items[-1] берёт последний элемент. len(items) показывает количество элементов.\n\nДля списка из трёх элементов индекс 3 уже выходит за границы. Будьте особенно внимательны с пустым списком.',
   'names = ["Ada", "Grace", "Linus"]\nprint(names[0])\nprint(len(names))','В names уже есть три имени. Сохраните first как первое, last как последнее и count как длину списка.','names = ["Ada", "Grace", "Linus"]\n',
   'names=["Ada","Grace","Linus"]\nfirst=names[0]\nlast=names[-1]\ncount=len(names)',[('Первый','first','Ada'),('Последний','last','Linus'),('Количество','count',3)],['Первый индекс — 0.','Последний элемент можно получить индексом -1.','len считает элементы, а не последний индекс.'])
py('list-update','Изменяем список','collections',
   'Список можно менять после создания. items.append(value) добавляет значение в конец. items[index] = value заменяет элемент на указанной позиции.\n\nМетод append изменяет существующий список и возвращает None. Поэтому не пишите items = items.append(...): так вы потеряете ссылку на список.\n\nДля удаления по позиции есть pop(index), а для удаления по значению — remove(value). Пока потренируем добавление и замену, чтобы увидеть разницу между изменяемым списком и неизменяемой строкой.',
   'tasks = ["читать"]\ntasks.append("писать")\ntasks[0] = "учиться"','Начните с numbers=[1,2]. Добавьте 3 в конец и замените первый элемент на 10.','numbers = [1, 2]\n',
   'numbers=[1,2]\nnumbers.append(3)\nnumbers[0]=10',[('Итоговый список','numbers',[10,2,3])],['append(3) расширит список.','Первая позиция имеет индекс 0.','Изменения дают [10, 2, 3], сохраняя порядок остальных элементов.'])
py('function-first','Функция: дать действию имя','functions',
   'Когда действие понадобится несколько раз, его можно оформить в функцию. def начинает определение, затем идут имя, скобки и двоеточие. Тело записывается с отступом. Само определение ещё не выполняет тело: для этого функцию вызывают.\n\nПараметр — входное значение. При вызове square(4) внутри функции number получает 4. return возвращает результат вызывающему коду. print только показывает текст и не заменяет return.\n\nСначала прочитайте определение, затем мысленно подставьте разные аргументы. Это тот же код, но новые входные данные.',
   'def square(number):\n    return number * number\n\nprint(square(4))','Создайте double(number), которая возвращает число, умноженное на 2.','def double(number):\n    # Замените pass\n    pass',
   'def double(number):\n    return number*2',[('Пять','double(5)',10),('Ноль','double(0)',0),('Отрицательное','double(-3)',-6)],['Параметр number уже содержит аргумент вызова.','Вычислите number * 2.','Верните результат через return, чтобы тест мог его прочитать.'])

# Simplify the early arithmetic task: it no longer requires functions before they are introduced.
l=original['python-arithmetic'];l.update(task='Создайте price=100, quantity=3 и discount=20. Сохраните total как price * quantity - discount и выведите его.',starterCode='price = 100\nquantity = 3\ndiscount = 20\n# Создайте total\n',tests=[{'id':'t1','label':'Стоимость','expression':'total','expected':280},{'id':'t2','label':'Вывод','expression':'_stdout','expected':'280\n'}],theory='Теперь вы умеете сохранять числа в переменные. Можно построить выражение из их имён: Python сначала прочитает текущие значения, затем вычислит результат.\n\nВ стоимости покупки price * quantity - discount сначала считается умножение, затем вычитается скидка. Если скидка относилась бы к каждой единице, формула была бы другой: (price - discount) * quantity. Скобки отражают смысл задачи.\n\n/ возвращает дробное число, // — целую часть с округлением вниз, % — остаток. Для этой покупки нужны только * и -. Перед Check убедитесь через Run, что показано ожидаемое число.',hints=['Умножьте цену на количество.','Скидка вычитается один раз из общей суммы.','Присвойте выражение переменной total и вызовите print(total).'])
solutions[l['id']]='price=100\nquantity=3\ndiscount=20\ntotal=price*quantity-discount\nprint(total)'

seed=original['sql-select']['setupSql']
def sql(slug,title,tag,theory,example,task,solution,expected,steps):
    return add('sql',slug,title,tag,theory,example,task,'-- Напишите запрос\n',solution,[('Результат запроса','$result',expected)],steps,setup=seed)
sql('first-values','Что такое SQL: первый запрос','start',
    'База данных хранит упорядоченную информацию. Таблица похожа на лист: столбцы описывают свойства, строки — отдельные записи. В учебной базе users каждая строка — человек, а name и age — его имя и возраст.\n\nSQL — язык запросов. SELECT означает «выбрать». Можно начать даже без таблицы: SELECT 2 + 3 вычислит выражение. Точка с запятой завершает запрос. Run выполнит его и покажет таблицу результата.\n\nSQL в этом курсе выполняет SQLite. Это встроенная база, которой не нужен отдельный сервер. Курс PostgreSQL использует другой движок и изучает его особенности.',
    "SELECT 'Привет, база!' AS message;",'Верните одну строку с одним числом: результатом 2 + 3.','SELECT 2 + 3;',[[5]],['Напишите SELECT.','Укажите выражение 2 + 3 и завершите запрос точкой с запятой.','В таблице OUTPUT будет одна ячейка со значением 5.'])
sql('columns','Столбец, строка и имя таблицы','select',
    'В таблице users есть столбцы id, name, age, department_id и active. id — уникальный номер, name — текст. Каждая строка описывает одного пользователя.\n\nSELECT name FROM users выбирает значения одного столбца из всех строк. SELECT * выбирает все столбцы. Если нужны только имена, перечислить name понятнее, чем брать всё.\n\nПорядок строк без ORDER BY не обещан. Для стабильного результата добавим ORDER BY id: меньший идентификатор будет первым.',
    'SELECT id, name FROM users ORDER BY id;','Выберите только name всех пользователей, отсортировав строки по id.','SELECT name FROM users ORDER BY id;',[['Ada'],['Linus'],['Grace'],['Alan']],['После SELECT укажите name.','После FROM укажите users.','ORDER BY id фиксирует порядок четырёх строк.'])
sql('aliases','Понятные названия: AS','select',
    'Псевдоним — имя столбца в результате запроса. AS не переименовывает столбец исходной таблицы; он только подписывает результат. Это полезно для вычислений.\n\nSELECT age + 1 AS next_age показывает возраст через год. Исходный age остаётся прежним, потому что SELECT читает, а не обновляет данные.\n\nВ SQLite многие выражения доступны прямо в SELECT. Проверяйте, что вы выбираете нужного человека, а не все строки: для этого используется WHERE.',
    'SELECT age + 1 AS next_age FROM users WHERE id = 1;','Для пользователя id=1 выберите name и age + 1. Назовите вычисляемый столбец next_age.','SELECT name, age+1 AS next_age FROM users WHERE id=1;',[['Ada',29]],['Выберите два выражения через запятую.','Вычисляемому столбцу задайте AS next_age.','WHERE id=1 оставляет Ada, её возраст в результате будет 29.'])
sql('distinct','Убираем повторения: DISTINCT','select',
    'Обычный SELECT возвращает значение для каждой подходящей строки. В users два человека работают в отделе 1, поэтому department_id повторяется. DISTINCT оставляет уникальные комбинации выбранных столбцов.\n\nЕсли выбрать два столбца, уникальность проверяется по их паре. DISTINCT не удаляет записи из базы. Он меняет только результат чтения.\n\nУ Alan отдел отсутствует и хранится как NULL. В задаче исключим отсутствующие значения через IS NOT NULL.',
    'SELECT DISTINCT active FROM users ORDER BY active;','Выберите уникальные ненулевые department_id и отсортируйте их по возрастанию.','SELECT DISTINCT department_id FROM users WHERE department_id IS NOT NULL ORDER BY department_id;',[[1],[2]],['После SELECT добавьте DISTINCT.','Исключите NULL с помощью WHERE.','Два пользователя отдела 1 дадут в результате только одну строку 1.'])
sql('operators','Объединяем условия: AND и OR','where',
    'AND требует выполнения обоих условий. OR достаточно хотя бы одного. Например, age >= 25 AND active = 1 оставляет только взрослых активных пользователей.\n\nAND имеет больший приоритет, чем OR. Чтобы запрос было легко читать и не ошибиться, используйте скобки вокруг логических групп.\n\nSELECT ничего не изменяет: можно безопасно посмотреть разные фильтры и сравнить выбранные строки.',
    'SELECT name FROM users WHERE age >= 25 AND active = 1 ORDER BY id;','Выберите name пользователей отдела 1, которым меньше 30 лет. Сортируйте по id.','SELECT name FROM users WHERE department_id=1 AND age<30 ORDER BY id;',[['Ada']],['Нужны два сравнения.','Оба должны выполняться, поэтому соедините их AND.','Ada подходит по отделу и возрасту; Linus не проходит вторую проверку.'])
sql('null','Отсутствующее значение: NULL','where',
    'NULL означает отсутствие известного значения. Это не ноль и не пустая строка. У Alan department_id равен NULL: отдел не назначен.\n\nСравнение department_id = NULL не работает как проверка равенства обычных чисел. Используйте IS NULL, а для наличия значения — IS NOT NULL.\n\nCOUNT(column) пропускает NULL, COUNT(*) считает строки. Мы вернёмся к этому в теме агрегатов.',
    'SELECT name FROM users WHERE department_id IS NULL;','Выберите имя пользователя без назначенного отдела.','SELECT name FROM users WHERE department_id IS NULL ORDER BY id;',[['Alan']],['Нужно проверить отсутствие department_id.','Используйте IS NULL вместо = NULL.','В исходной базе только Alan не имеет отдела.'])
sql('like','Поиск текста: LIKE','where',
    'LIKE сравнивает текст с шаблоном. Символ % означает любое количество символов, включая ноль; _ означает один символ. Шаблон задаётся строкой в одинарных кавычках.\n\nШаблон A% ищет начало на A, а %a% ищет букву внутри строки. Поиск не меняет данные.\n\nSQLite по умолчанию нечувствителен к регистру ASCII в LIKE, но правила Unicode сложнее. В PostgreSQL LIKE чувствителен к регистру, а ILIKE даёт регистронезависимый поиск.',
    "SELECT name FROM users WHERE name LIKE 'L%';",'Выберите имена, которые начинаются на A. Порядок — по id.',"SELECT name FROM users WHERE name LIKE 'A%' ORDER BY id;",[['Ada'],['Alan']],['Начало шаблона — буква A.','После неё поставьте %, разрешающий любое продолжение.','Вы получите Ada и Alan в порядке id.'])
sql('in','Список допустимых значений: IN','where',
    'IN проверяет, находится ли значение в перечисленном наборе. id IN (1, 3) означает id = 1 OR id = 3. Для длинного списка IN читается проще.\n\nЗначения перечисляются через запятую в круглых скобках. Для текста нужны кавычки; для чисел — нет. NOT IN означает отсутствие в наборе, но требует осторожности с NULL.\n\nПозже набор значений можно будет получать вложенным запросом.',
    'SELECT name FROM users WHERE id IN (1, 2) ORDER BY id;','Выберите имена пользователей с id 1 и 3. Порядок — по id.','SELECT name FROM users WHERE id IN (1,3) ORDER BY id;',[['Ada'],['Grace']],['Перечислите 1 и 3 внутри IN (...).','Не пишите id=1 AND id=3: одна строка не может иметь сразу оба id.','Выбранными окажутся Ada и Grace.'])
sql('between','Диапазон с границами: BETWEEN','where',
    'BETWEEN lower AND upper включает обе границы. age BETWEEN 20 AND 30 означает age >= 20 AND age <= 30. Это отличается от Python range, в котором правая граница не включается.\n\nПорядок границ важен: сначала меньшая, потом большая. Диапазон удобно использовать для чисел и дат в согласованном формате.\n\nНачинайте проверку с граничных значений: именно на них часто возникают ошибки.',
    'SELECT name FROM users WHERE age BETWEEN 20 AND 30 ORDER BY id;','Выберите name и age людей от 22 до 28 лет включительно. Порядок — по id.','SELECT name,age FROM users WHERE age BETWEEN 22 AND 28 ORDER BY id;',[['Ada',28],['Grace',22]],['Используйте нижнюю границу 22.','Верхняя граница 28 тоже включается.','Обе найденные строки лежат ровно на границах диапазона.'])
sql('limit','Сортировка и первые N строк','order',
    'ORDER BY age DESC располагает возраст по убыванию: сначала самый большой. LIMIT 2 оставляет первые две строки уже сформированного результата.\n\nБез ORDER BY фраза «первые две строки» не означает конкретных пользователей. Если значения совпадают, добавьте второй ключ сортировки, например id.\n\nOFFSET позволяет пропустить строки и полезен для страниц результата. Пока возьмём только двух самых старших пользователей.',
    'SELECT name,age FROM users ORDER BY age DESC, id LIMIT 2;','Покажите name и age двух самых старших пользователей, сортируя возраст по убыванию.','SELECT name,age FROM users ORDER BY age DESC,id LIMIT 2;',[['Linus',34],['Ada',28]],['Сначала задайте ORDER BY age DESC.','Добавьте LIMIT 2 в конец.','После сортировки первые два возраста — 34 и 28.'])
sql('count','Считаем строки: COUNT','aggregate',
    'Агрегатная функция получает много строк и возвращает общий итог. COUNT(*) считает число строк после WHERE. COUNT(column) считает только значения, которые не равны NULL.\n\nВ users четыре человека, но department_id заполнен у троих. Поэтому COUNT(*) и COUNT(department_id) дадут разные результаты.\n\nИтог без GROUP BY будет одной строкой. AS помогает назвать его понятным словом.',
    'SELECT COUNT(*) AS total FROM users;','Верните два числа: количество всех пользователей и количество заполненных department_id.','SELECT COUNT(*),COUNT(department_id) FROM users;',[[4,3]],['Первое выражение — COUNT(*).','Второе считает конкретный столбец.','NULL у Alan не входит во второй счётчик.'])
sql('sum','Сумма значений: SUM','aggregate',
    'SUM складывает значения столбца после отбора строк. Например, можно сложить цены заказов или длительности работ. В учебной базе потренируем механизм на возрасте.\n\nWHERE применяется до SUM, поэтому отбор отдела меняет входные строки агрегата. NULL игнорируется; при полном отсутствии значений SUM возвращает NULL, а не ноль.\n\nДля замены отсутствующего результата можно использовать COALESCE, но сначала важно понимать причину NULL.',
    'SELECT SUM(age) FROM users WHERE active = 1;','Верните сумму возрастов пользователей из отдела 1.','SELECT SUM(age) FROM users WHERE department_id=1;',[[62]],['Сначала мысленно выберите Ada и Linus.','Передайте age в SUM.','28 + 34 = 62; результат содержит одну строку.'])
sql('average','Среднее, минимум и максимум','aggregate',
    'AVG вычисляет среднее арифметическое ненулевых значений. MIN возвращает наименьшее, MAX — наибольшее. Несколько агрегатов можно вывести одной строкой.\n\nСреднее не обязательно целое. Для возрастов 28 и 34 оно равно 31. SQLite обычно возвращает для AVG дробное числовое значение, даже если в нём нет дробной части.\n\nЕсли нужно группировать людей по отделам, это будет следующий шаг с GROUP BY.',
    'SELECT MIN(age),MAX(age),AVG(age) FROM users;','Для отдела 1 верните MIN(age), MAX(age) и AVG(age), в таком порядке.','SELECT MIN(age),MAX(age),AVG(age) FROM users WHERE department_id=1;',[[28,34,31]],['Ограничьте строки условием department_id=1.','Перечислите три функции через запятую.','Минимум 28, максимум 34, среднее 31.'])
sql('subquery','Запрос внутри запроса','subquery',
    'Вложенный запрос вычисляет данные, которые нужны внешнему запросу. Если он возвращает одно значение, его можно использовать справа от сравнения. Круглые скобки отделяют его от внешнего SQL.\n\nЧтобы найти людей старше среднего, сначала вычислите средний возраст, затем сравните с ним age каждой строки. Не нужно вручную переносить число из OUTPUT в новый запрос.\n\nЕсли скалярный подзапрос неожиданно возвращает несколько строк, поведение зависит от СУБД: PostgreSQL выдаст ошибку, SQLite может взять первую строку. Следите за формой результата.',
    'SELECT name FROM users WHERE age > (SELECT AVG(age) FROM users) ORDER BY id;','Выберите имена пользователей старше среднего возраста всех пользователей. Порядок — по id.','SELECT name FROM users WHERE age>(SELECT AVG(age) FROM users) ORDER BY id;',[['Ada'],['Linus']],['Внутренний SELECT возвращает AVG(age).','Сравните age внешней строки с этим значением.','Среднее 25.75; Ada и Linus старше него.'])

pgseed="CREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,age INTEGER,active BOOLEAN); INSERT INTO users VALUES(1,'Ada',28,TRUE),(2,'Linus',34,TRUE),(3,'Grace',22,FALSE);"
def pg(slug,title,tag,theory,example,task,solution,tests,steps):
    return add('postgresql',slug,title,tag,theory,example,task,'-- PostgreSQL / PGlite\n',solution,tests,steps,setup=pgseed)
pg('first','Знакомство с PostgreSQL','start','PostgreSQL — другая СУБД, а не новое название SQLite. В DevForge используется PGlite: PostgreSQL, собранный в WebAssembly для локальной учебной среды. Для этих заданий не нужен отдельно установленный сервер.\n\nОсновные SELECT, WHERE и JOIN знакомы по SQLite. Но типы, функции и часть правил отличаются. PGlite подходит для изучения SQL PostgreSQL, но не заменяет практику администрирования многопользовательского сервера.\n\nНачнём с чтения таблицы users. Явно задавайте ORDER BY, чтобы результат был предсказуемым.','SELECT name, age FROM users ORDER BY id;','Выберите name и age пользователей с age >= 28, по id.','SELECT name,age FROM users WHERE age>=28 ORDER BY id;',[('Строки','$result',[['Ada',28],['Linus',34]])],['Оператор SELECT выбирает два столбца.','WHERE исключает Grace, которой 22 года.','ORDER BY id возвращает сначала Ada, затем Linus.'])
pg('boolean','Настоящий тип BOOLEAN','types','PostgreSQL хранит логические значения в типе BOOLEAN. Используйте TRUE, FALSE и NULL. В SQLite отдельного класса хранения boolean нет, и часто используют 0/1.\n\nWHERE active означает, что выражение active должно быть истинно. Проверка active = TRUE тоже допустима. Не подставляйте привычное active = 1: строгая типизация PostgreSQL различает boolean и integer.','SELECT name FROM users WHERE active;','Выберите имена активных пользователей по id.','SELECT name FROM users WHERE active ORDER BY id;',[('Активные','$result',[['Ada'],['Linus']])],['active уже логическое выражение.','Не сравнивайте его с числом 1.','WHERE active оставит две строки со значением TRUE.'])
pg('casts','Явное преобразование типа','types','В PostgreSQL тип выражения важен. Оператор :: задаёт явное преобразование: текст \'42\'::integer становится числом. Переносимая форма той же операции — CAST(value AS type).\n\nНекорректный текст вызывает ошибку преобразования, а не молча превращается в другое значение. Выбирайте тип по смыслу: INTEGER для целых счётчиков, NUMERIC для точных десятичных вычислений.','SELECT \'12\'::integer + 3;','Преобразуйте текст \'42\' в INTEGER, прибавьте 8 и верните результат.','SELECT \'42\'::integer + 8;',[('Число','$result',[[50]])],['К строке примените ::integer.','После преобразования выполняется числовое сложение.','Результат — число 50, не строка 428.'])
pg('ilike','Поиск без учёта регистра: ILIKE','where','LIKE в PostgreSQL учитывает регистр. ILIKE предназначен для поиска без учёта регистра согласно выбранной локали. Это расширение PostgreSQL, которого нет как отдельного оператора в SQLite.\n\nПроцент % означает любое продолжение, подчёркивание _ — один символ. Не путайте поиск шаблона с регулярными выражениями: у них разные операторы и правила.','SELECT name FROM users WHERE name ILIKE \'a%\';','Найдите пользователя, имя которого начинается на a без учёта регистра.','SELECT name FROM users WHERE name ILIKE \'a%\' ORDER BY id;',[('Имя','$result',[['Ada']])],['В таблице имя начинается с заглавной A.','Оператор ILIKE позволит шаблону a% совпасть с Ada.','Остальные имена не начинаются с этой буквы.'])
pg('returning','INSERT с результатом: RETURNING','write','Обычно INSERT изменяет таблицу. RETURNING позволяет сразу получить поля вставленной записи. Это удобно для автоматически созданного id и значений по умолчанию.\n\nRETURNING поддерживается современными PostgreSQL и SQLite, но поведение и возможности сложных запросов различаются. Здесь изучаем результат конкретной вставки в PostgreSQL.','INSERT INTO users VALUES(4,\'Alan\',19,TRUE) RETURNING id,name;','Добавьте (4, \'Alan\', 19, TRUE). Верните id и name вставленной строки.','INSERT INTO users VALUES(4,\'Alan\',19,TRUE) RETURNING id,name;',[('RETURNING','$result',[[4,'Alan']]),('Запись сохранена','SELECT age,active FROM users WHERE id=4',[[19,True]])],['Перечислите значения в порядке столбцов.','Добавьте RETURNING id,name после VALUES.','Проверка также читает сохранённую строку из базы.'])
pg('json','Структурированные данные: JSONB','json','JSONB хранит структурированные документы: объекты и массивы. В PostgreSQL доступны операторы доступа к их полям. -> возвращает JSON-значение, ->> возвращает текст.\n\nЧтобы превратить строковый литерал в JSONB, используйте ::jsonb. Имена полей внутри JSON должны быть в двойных кавычках. Весь SQL-литерал окружается одинарными кавычками.','SELECT \'{"name":"Ada"}\'::jsonb ->> \'name\';','Из документа {"name":"Ada","level":2} верните поле name как текст.','SELECT \'{"name":"Ada","level":2}\'::jsonb ->> \'name\';',[('Текст поля','$result',[['Ada']])],['Литерал преобразуется через ::jsonb.','Для текстового результата нужен ->>.','Ключ name указывается SQL-строкой в одинарных кавычках.'])
pg('cte','Именуем шаг запроса: WITH','subquery','CTE — общий табличный запрос. WITH даёт имя промежуточному результату, который используется ниже. Это помогает разбить большой запрос на понятные части.\n\nCTE существует только в рамках одного SQL-выражения: это не сохранённая таблица. Внутри него можно выбирать, фильтровать и группировать строки.\n\nСначала прочитайте часть в скобках, затем основной SELECT, который обращается к её имени.','WITH adults AS (SELECT name,age FROM users WHERE age>=28) SELECT name FROM adults ORDER BY name;','Создайте CTE adults для age>=28 и верните name из него в алфавитном порядке.','WITH adults AS (SELECT name,age FROM users WHERE age>=28) SELECT name FROM adults ORDER BY name;',[('Имена','$result',[['Ada'],['Linus']])],['WITH adults AS (...) задаёт промежуточную выборку.','Внутри используйте WHERE age>=28.','Внешний SELECT читает adults и сортирует name.'])
pg('window','Нумерация без группировки','window','Оконная функция вычисляет значение рядом с каждой строкой, не схлопывая их в группы. ROW_NUMBER() нумерует строки в порядке, указанном в OVER.\n\nORDER BY внутри OVER определяет нумерацию, а внешний ORDER BY — порядок вывода. Для однозначности при равных возрастах добавьте id как второй ключ.\n\nОконные функции существуют и в современной SQLite, но PostgreSQL предлагает собственный набор возможностей.','SELECT name, ROW_NUMBER() OVER (ORDER BY age DESC,id) AS place FROM users ORDER BY place;','Пронумеруйте пользователей по убыванию возраста. Верните name и номер, сортируя по номеру.','SELECT name,ROW_NUMBER() OVER(ORDER BY age DESC,id) AS place FROM users ORDER BY place;',[('Рейтинг','$result',[['Linus',1],['Ada',2],['Grace',3]])],['ROW_NUMBER() требует OVER (...).','В окне задайте age DESC,id.','Строки остаются отдельными: Linus получает номер 1.'])

def web(slug,title,tag,theory,example,task,starter,solution,tests,steps):
    l=add('html-css',slug,title,tag,theory,example,task,starter,solution,[],steps)
    l['tests']=[dict(id=f't{i+1}',label=t[0],dom=t[1],expected=t[2]) for i,t in enumerate(tests)]
    return l
web('first','Первая веб-страница','start','HTML описывает структуру страницы: где заголовок, абзац, список. Это язык разметки, а не набор вычислений как Python. Браузер читает разметку и рисует страницу.\n\nЭлемент обычно состоит из открывающего тега, содержимого и закрывающего тега: <p>Текст</p>. У закрывающего тега есть /. Заголовок первого уровня обозначается h1.\n\nRun откроет предпросмотр рядом с результатами. Он изолирован от DevForge: скрипты и внешние ресурсы в учебном preview отключены.','<h1>Моя страница</h1>\n<p>Первый абзац.</p>','Добавьте h1 с текстом Привет, web! и абзац p с текстом Я учусь создавать сайты.','<!-- Напишите разметку -->','<h1>Привет, web!</h1>\n<p>Я учусь создавать сайты.</p>',[('Заголовок',{'selector':'h1','property':'text'},'Привет, web!'),('Абзац',{'selector':'p','property':'text'},'Я учусь создавать сайты.')],['Создайте пару тегов h1 и поместите внутрь текст.','Следующим элементом добавьте p.','Run покажет заголовок крупнее абзаца: это стили браузера по умолчанию.'])
web('structure','Каркас HTML-документа','structure','Полный документ начинается с <!doctype html>. Эта строка включает современный режим отображения. html содержит две основные части: head с метаданными и body с видимым содержимым.\n\nВ head полезны meta charset="UTF-8" и title. Кодировка позволяет корректно показывать русский текст; title — название документа. В body находятся заголовки и абзацы.\n\nАтрибут lang="ru" сообщает язык содержимого и помогает средствам доступности.','<!doctype html>\n<html lang="ru">\n<head><meta charset="UTF-8"><title>Пример</title></head>\n<body><h1>Пример</h1></body>\n</html>','Создайте документ lang="ru", title «Моя мастерская» и h1 «DevForge».','<!doctype html>\n<html>\n<head></head>\n<body></body>\n</html>','<!doctype html><html lang="ru"><head><meta charset="UTF-8"><title>Моя мастерская</title></head><body><h1>DevForge</h1></body></html>',[('Язык',{'selector':'html','property':'attr','attribute':'lang'},'ru'),('Название',{'selector':'title','property':'text'},'Моя мастерская'),('Заголовок',{'selector':'h1','property':'text'},'DevForge')],['Сначала разделите head и body.','title относится к head, h1 — к body.','У html укажите lang="ru"; русскому тексту помогает meta charset.'])
web('lists','Списки: ul и li','structure','ul — неупорядоченный список. Его элементы обозначаются li. Браузер добавляет маркеры; руками печатать дефисы не нужно. ol создаёт нумерованный список.\n\nВложенность важна: li размещаются внутри ul или ol. Каждый элемент закрывается до начала следующего. Отступы в HTML помогают читать структуру, хотя обычно не меняют её смысл.','<ul>\n  <li>Читать</li>\n  <li>Практиковаться</li>\n</ul>','Создайте ul из трёх li: HTML, CSS, Практика — в таком порядке.','','<ul><li>HTML</li><li>CSS</li><li>Практика</li></ul>',[('Пункты',{'selector':'ul > li','property':'texts'},['HTML','CSS','Практика'])],['Откройте ul.','Для каждого пункта создайте отдельный li.','Закройте ul после третьего пункта.'])
web('links','Атрибуты и ссылки','structure','Атрибуты добавляют свойства открывающему тегу. В ссылке a атрибут href задаёт адрес перехода, а текст между тегами — видимое название.\n\nСсылка href="#practice" указывает на элемент той же страницы с id="practice". id должен быть уникальным. Такой переход удобен для оглавления длинной страницы.\n\nВ изолированном preview переход наружу отключён; здесь тренируем безопасную ссылку на раздел.','<a href="#about">О разделе</a>\n<section id="about">Описание</section>','Добавьте ссылку «К практике» на #practice и section с id="practice".','','<a href="#practice">К практике</a><section id="practice">Упражнение</section>',[('Адрес',{'selector':'a','property':'attr','attribute':'href'},'#practice'),('Название ссылки',{'selector':'a','property':'text'},'К практике'),('Раздел',{'selector':'section#practice','property':'count'},1)],['href хранится в открывающем теге a.','Значение #practice ссылается на id, без # в самом id.','Текст ссылки объясняет пользователю, куда он перейдёт.'])
web('css-first','Первое правило CSS','css','HTML задаёт структуру, CSS — внешний вид. Правило CSS состоит из селектора и блока свойств в фигурных скобках. Селектор p выбирает абзацы; color задаёт цвет текста.\n\nСвойство и значение разделяются двоеточием, а объявления заканчиваются точкой с запятой. CSS можно разместить в элементе style. В проектах можно также использовать отдельный файл .css.\n\nМеняйте одно свойство за раз и запускайте предпросмотр, чтобы увидеть его влияние.','<style>p { color: blue; }</style>\n<p>Цветной текст</p>','Сделайте текст единственного h1 красным через CSS. Содержимое заголовка — Мой стиль.','<h1>Мой стиль</h1>','<style>h1 { color: red; }</style><h1>Мой стиль</h1>',[('Заголовок',{'selector':'h1','property':'text'},'Мой стиль'),('Цвет',{'selector':'h1','property':'style','css':'color'},'rgb(255, 0, 0)')],['Создайте style перед заголовком.','Селектор h1 выбирает заголовок.','Объявление color: red меняет цвет; Check читает вычисленный стиль браузера.'])
web('classes','Классы и выбор элементов','css','Класс позволяет объединить элементы для оформления. В HTML пишется class="note", а в CSS селектор начинается с точки: .note. Один класс может встречаться у нескольких элементов.\n\nЕсли написать note без точки, CSS будет искать тег с таким именем. Атрибут id выбирается через #, но для повторяемых компонентов чаще подходят классы.\n\nРазделение структуры и стилей позволяет менять внешний вид, не переписывая текст каждого элемента.','<style>.note { font-weight: 700; }</style>\n<p class="note">Важно</p>','Добавьте p класса note с текстом Важно. Установите для .note font-weight: 700.','','<style>.note{font-weight:700}</style><p class="note">Важно</p>',[('Класс и текст',{'selector':'p.note','property':'text'},'Важно'),('Толщина',{'selector':'.note','property':'style','css':'font-weight'},'700')],['Добавьте атрибут class к p.','В CSS перед названием класса поставьте точку.','Значение 700 соответствует жирному начертанию.'])
web('box','Блочная модель и отступы','layout','У элемента есть содержимое, внутренний отступ padding, рамка border и внешний отступ margin. Padding отодвигает содержимое от рамки, margin — соседние элементы друг от друга.\n\nПо умолчанию width задаёт ширину содержимого. box-sizing: border-box включает padding и border в указанную ширину, поэтому размеры проще предсказывать.\n\nПиксели px — единица CSS, а не обязательно физические пиксели монитора.','<style>.card { padding: 16px; border: 1px solid gray; box-sizing: border-box; }</style>\n<div class="card">Карточка</div>','Для .card задайте padding:16px, width:200px и box-sizing:border-box. Добавьте div класса card.','','<style>.card{padding:16px;width:200px;box-sizing:border-box}</style><div class="card">Карточка</div>',[('Внутренний отступ',{'selector':'.card','property':'style','css':'padding-top'},'16px'),('Ширина',{'selector':'.card','property':'style','css':'width'},'200px'),('Модель',{'selector':'.card','property':'style','css':'box-sizing'},'border-box')],['Добавьте div с нужным классом.','Укажите три свойства в одном CSS-правиле.','Внешняя ширина останется 200px, потому что padding включён в border-box.'])
web('flex','Раскладка Flexbox','layout','Flexbox размещает дочерние элементы вдоль одной основной оси. display:flex включается у контейнера, а не у каждого ребёнка. По умолчанию основная ось идёт горизонтально.\n\njustify-content управляет размещением вдоль основной оси, align-items — вдоль поперечной. gap задаёт промежуток между элементами.\n\nНачинайте с контейнера и двух небольших блоков, затем меняйте по одному свойству и смотрите результат.','<style>.row { display:flex; gap:12px; }</style>\n<div class="row"><span>A</span><span>B</span></div>','Создайте .row с display:flex и gap:12px. Внутри разместите два span с текстами A и B.','','<style>.row{display:flex;gap:12px}</style><div class="row"><span>A</span><span>B</span></div>',[('Раскладка',{'selector':'.row','property':'style','css':'display'},'flex'),('Промежуток',{'selector':'.row','property':'style','css':'gap'},'12px'),('Дочерние элементы',{'selector':'.row > span','property':'texts'},['A','B'])],['Включите flex у .row.','gap создаёт промежуток между дочерними элементами.','Два span станут соседями по горизонтали.'])
web('grid','Сетка CSS Grid','layout','Grid размещает элементы по строкам и столбцам. display:grid включается у контейнера. grid-template-columns описывает ширины столбцов.\n\nЕдиница fr делит свободное пространство. Запись repeat(2, 1fr) создаёт два равных столбца. gap задаёт расстояние между ячейками. В отличие от таблицы данных, CSS Grid — способ оформления, а не семантика данных.','<style>.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}</style>\n<div class="grid"><div>1</div><div>2</div></div>','Создайте .grid с display:grid и gap:8px. Добавьте четыре дочерних div с числами 1–4 и задайте два столбца.','','<style>.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}</style><div class="grid"><div>1</div><div>2</div><div>3</div><div>4</div></div>',[('Grid',{'selector':'.grid','property':'style','css':'display'},'grid'),('Отступ',{'selector':'.grid','property':'style','css':'gap'},'8px'),('Ячейки',{'selector':'.grid > div','property':'texts'},['1','2','3','4']),('Два столбца',{'selector':'.grid','property':'columns'},2)],['Контейнер получает display:grid.','repeat(2,1fr) делит ширину на две равные колонки.','Четыре блока займут две строки по две колонки.'])
web('semantics','Семантика и доступная форма','accessibility','Семантический HTML объясняет назначение элементов: main — основное содержимое, nav — навигация, button — действие. Так странице проще пользоваться с клавиатуры и экранного диктора.\n\nПоле ввода должно иметь подпись. label for="name" связывается с input id="name". placeholder не заменяет подпись: он исчезает при вводе.\n\nВ этом курсе формы не отправляются во внешнюю сеть. Мы проверяем структуру и связь подписи с полем.','<label for="email">Почта</label>\n<input id="email" type="email">\n<button type="button">Проверить</button>','Внутри main добавьте label «Имя» с for="name", input id="name" и button type="button" с текстом Сохранить.','','<main><label for="name">Имя</label><input id="name" type="text"><button type="button">Сохранить</button></main>',[('Основное содержимое',{'selector':'main','property':'count'},1),('Связь подписи',{'selector':'label','property':'attr','attribute':'for'},'name'),('Поле',{'selector':'input#name','property':'count'},1),('Кнопка',{'selector':'button','property':'attr','attribute':'type'},'button'),('Текст кнопки',{'selector':'button','property':'text'},'Сохранить')],['Создайте main как контейнер.','for у label должен совпадать с id поля.','Нативная кнопка уже умеет получать фокус с клавиатуры.'])

orders={
'python':'first-print comments numbers text-quotes variable-step variables arithmetic conversion booleans comparisons if-first range-first while-counter list-index list-update function-first functions strings conditions loops lists dictionaries exceptions classes'.split(),
'sql':'first-values columns select aliases where operators null like in between distinct limit count sum average group insert update delete create types constraints join subquery'.split(),
'postgresql':'first boolean casts ilike returning json cte window'.split(),
'html-css':'first structure lists links css-first classes box flex grid semantics'.split()}
legacy_tags={'variables':'variables','arithmetic':'numbers','strings':'strings','conditions':'conditions','loops':'loops','lists':'collections','dictionaries':'collections','functions':'functions','exceptions':'errors','classes':'objects','select':'select','where':'where','insert':'write','update':'write','delete':'write','create':'schema','types':'types','constraints':'schema','group':'aggregate','join':'join'}
result=[]
for lang,slugs in orders.items():
    for i,slug in enumerate(slugs):
        l=original[f'{lang}-{slug}'];l['order']=i+1;l['minutes']=7+min(i//3,8)
        l['concepts']=l.get('concepts',[legacy_tags.get(slug,'start')])
        l['section']='С нуля' if i<5 else 'Основы' if i<12 else 'Практика и применение'
        l['level']='Beginner' if i<12 else 'Elementary'
        l['walkthrough']=l.get('walkthrough',['Прочитайте условие и найдите входные данные в стартовом коде.','Разберите пример: что вычисляется и где получается результат?','Напишите своё решение, нажмите Run и сравните вывод. Затем Check проверит несколько случаев.'])
        l['prerequisites']=[f'{lang}-{slugs[i-1]}'] if i else []
        result.append(l)
(CONTENT/'lessons.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8')
docs=[dict(id=l['id'],title=l['title'],language=l['language'],category=l['section'],explanation=l['theory'],syntax=l['syntax'],example=l['examples'][0],mistakes=l['commonMistakes'],relatedLessons=[l['id']]) for l in result]
(CONTENT/'documentation.json').write_text(json.dumps(docs,ensure_ascii=False,indent=2),encoding='utf-8')
(ROOT/'frontend/tests/solutions.json').write_text(json.dumps(solutions,ensure_ascii=False,indent=2),encoding='utf-8')
languages=json.loads((CONTENT/'languages.json').read_text(encoding='utf-8'))
for lang in languages:
    if lang['id'] in orders:
        lang['status']='available';lang['supportedFeatures']=['run','check','reset','files']
    if lang['id']=='postgresql':lang.update(runnerType='pglite-worker',description='PostgreSQL в WebAssembly. SQL-диалект, типы, JSONB и оконные функции без отдельного сервера.',editorLanguage='sql')
    if lang['id']=='html-css':lang.update(runnerType='sandbox-preview',description='HTML и CSS с живым изолированным предпросмотром и проверками DOM/стилей.')
(CONTENT/'languages.json').write_text(json.dumps(languages,ensure_ascii=False,indent=2),encoding='utf-8')
print({lang:len(slugs) for lang,slugs in orders.items()},'total',len(result))
